// Convierte el payload de Meta en 1 item por mensaje recibido.
// - Recorre TODOS los entry/changes/messages (Meta puede agrupar varios).
// - Ignora los webhooks de estado (sent/delivered/read): devuelve [] y la
//   ejecución termina aquí sin tocar la base de datos.
const BIENVENIDA = (nombre) =>
  `Hola ${nombre || ''}, gracias por escribirnos. ¿En qué te podemos ayudar?`.replace('Hola ,', 'Hola,');

function extraerTexto(m) {
  switch (m.type) {
    case 'text':        return m.text?.body ?? '';
    case 'button':      return m.button?.text ?? '';
    case 'interactive': return m.interactive?.button_reply?.title
                            ?? m.interactive?.list_reply?.title ?? '[interactive]';
    case 'image':
    case 'video':
    case 'document':    return m[m.type]?.caption || `[${m.type}]`;
    case 'location':    return `[location] ${m.location?.latitude},${m.location?.longitude}`;
    default:            return `[${m.type}]`;   // audio, sticker, reaction, etc.
  }
}

const out = [];
for (const item of $input.all()) {
  for (const entry of item.json.body?.entry ?? []) {
    for (const change of entry.changes ?? []) {
      const v = change.value ?? {};
      if (!Array.isArray(v.messages)) continue;

      const nombres = {};
      for (const c of v.contacts ?? []) nombres[c.wa_id] = c.profile?.name ?? '';

      for (const m of v.messages) {
        if (m.type === 'reaction') continue;   // no aporta a la conversación
        const nombre = nombres[m.from] ?? '';
        out.push({
          json: {
            wa_message_id: m.id,
            phone: m.from,
            nombre_cliente: nombre,
            tipo: m.type,
            mensaje_cliente: extraerTexto(m),
            ts: Number(m.timestamp) || Math.floor(Date.now() / 1000),
            texto_bienvenida: BIENVENIDA(nombre),
          },
        });
      }
    }
  }
}
return out;

